'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'NULL').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,progress={labs:[],quizzes:[]},current=-1,selectedAnswer=null;
try{const p=JSON.parse(localStorage.getItem('cinesuper-learning-v1'));if(p&&Array.isArray(p.labs)&&Array.isArray(p.quizzes))progress={labs:p.labs.filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length),quizzes:p.quizzes.filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length)};}catch{storageOK=false;}
const complete=i=>progress.labs.includes(i)&&progress.quizzes.includes(i);
const count=(m)=>lessons.filter((l,i)=>(!m||l.module===m)&&complete(i)).length;
function persist(){try{localStorage.setItem('cinesuper-learning-v1',JSON.stringify(progress));}catch{storageOK=false;toast('Progress cannot be saved in this browser. You can still finish the lessons.');}}
function toast(t){$('#toast').textContent=t;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4500);}
function mark(type){if(current<0)return;if(!progress[type].includes(current)){progress[type].push(current);persist();}updateStatus();}
function updateStatus(){const el=$('#checkpoint-status');if(el)el.textContent=complete(current)?'✓ Lesson complete — activity and knowledge check passed.':`Activity: ${progress.labs.includes(current)?'passed':'to do'} · Knowledge check: ${progress.quizzes.includes(current)?'passed':'to do'}`;$$('aside a[data-lesson]').forEach(a=>{const i=+a.dataset.lesson;a.querySelector('.status').textContent=complete(i)?'✓':'';});const label=$('#overall-label');if(label)label.textContent=`${count()} / ${lessons.length} lessons completed`;const bar=$('#overall-bar');if(bar)bar.style.width=`${count()/lessons.length*100}%`;}
function feedback(id,text,good){const e=document.getElementById(id);e.className='feedback '+(good?'good':'bad');e.textContent=text;}
function labPass(id,text){feedback(id,text,true);mark('labs');}
function table(rows,caption='',columns){const cols=columns||Object.keys(rows[0]||{});return `<div class="table-wrap"><table>${caption?`<caption>${esc(caption)}</caption>`:''}<thead><tr>${cols.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length||1}">No matching rows. Try another condition.</td></tr>`}</tbody></table></div>`;}
const opts=(values,chosen)=>values.map(v=>`<option ${v===chosen?'selected':''}>${esc(v)}</option>`).join('');
const statusBox=(id='lab-feedback',text='Make a choice, then test your idea.')=>`<div id="${id}" class="feedback" role="status" aria-live="polite">${text}</div>`;
function home(){current=-1;const next=lessons.findIndex((l,i)=>!complete(i));$('#app').innerHTML=`<main id="main" class="container"><section class="hero"><div><div class="eyebrow">Your first step into database design</div><h1>Learn databases.<br>One movie<br>at a <em>time.</em></h1><p class="lead">No experience? Perfect. Build your understanding of DBMS by exploring the world of CineSuper.</p><div class="hero-actions"><a class="primary accent" href="#lesson-${next<0?0:next}">${count()?'Continue learning':'Start learning'} <span>↗</span></a><a class="text-link" href="#database">Meet the database →</a></div><div class="micro">No setup. No coding required. Just curiosity.</div><div class="stats"><div><strong>02</strong><span>guided modules</span></div><div><strong>14</strong><span>hands-on lessons</span></div><div><strong>01</strong><span>familiar movie world</span></div></div></div><div class="scene" aria-label="CineSuper movie catalogue connected to three database tables"><div class="scene-label">NOW LEARNING AT CINESUPER</div><div class="poster-row"><div class="poster p1"><span class="symbol">◉</span><b>DRISHYAM</b><small>2013 · MALAYALAM</small></div><div class="poster p2"><span class="symbol">ϟ</span><b>MINNAL<br>MURALI</b><small>2021 · MALAYALAM</small></div><div class="poster p3"><span class="symbol">◎</span><b>INCEPTION</b><small>2010 · ENGLISH</small></div></div><div class="schema-float"><div class="schema-line"><span>genres</span><span>1 → N</span><span>movies</span><span>1 → N</span><span>reviews</span></div><code>Behind every movie card, there is a story in data.</code></div><div class="scene-foot">Browse it. Break it. Understand it.</div></div></section>${count()===14?'<div class="completion"><h3>Two modules. A whole new way to see data.</h3><p>You passed all 14 activities and knowledge checks. Revisit any lab or export your progress in Teacher notes.</p></div>':''}<section><div class="section-head"><div><h2>Your learning path</h2><p>Small ideas. Real examples. A chance to try every concept.</p></div><span class="pill">${count()} / 14 lessons complete</span></div><div class="module-grid">${[1,2].map(m=>{let ls=lessons.map((l,i)=>({...l,i})).filter(l=>l.module===m);return `<article class="module-card"><div class="module-top"><span class="module-no">MODULE 0${m}</span><span class="module-icon" aria-hidden="true">${m===1?'▦':'⇄'}</span></div><h3>${m===1?'Database concepts<br>& data modelling':'Relational model<br>& normalisation'}</h3><p>${m===1?'Discover how databases work. Give data an identity, draw its connections, and design your first schema.':'Ask questions of your data. Find dependencies, remove repetition, and make better design decisions.'}</p><ul>${ls.map(l=>`<li><a href="#lesson-${l.i}"><span class="lesson-number">${String(l.i+1).padStart(2,'0')}</span>${l.title}<span class="${complete(l.i)?'done':''}">${complete(l.i)?'✓':'↗'}</span></a></li>`).join('')}</ul><div class="progress-track"><span style="width:${count(m)/ls.length*100}%"></span></div><div class="module-bottom"><span>${ls.length} lessons · about ${m===1?'65':'110'} min</span><a class="text-link" href="#lesson-${ls.find(l=>!complete(l.i))?.i??ls[0].i}">${count(m)?'Continue':'Explore module'} →</a></div></article>`;}).join('')}</div></section><section class="how"><div><div class="step-label">01 / UNDERSTAND</div><strong>Start with something familiar.</strong><p>Every explanation comes back to movies, genres, and reviews.</p></div><div><div class="step-label">02 / EXPERIMENT</div><strong>Learn with your hands.</strong><p>Change a value, connect an entity, or split a table. See what happens.</p></div><div><div class="step-label">03 / MAKE IT STICK</div><strong>Check your understanding.</strong><p>Get feedback, use a hint, and try again. Your browser remembers progress.</p></div></section></main>`;}
function sidebar(){return `<aside aria-label="Lesson navigation"><a href="#home">← Learning path</a>${[1,2].map(m=>`<div class="eyebrow">Module ${m}</div>${lessons.map((l,i)=>l.module===m?`<a href="#lesson-${i}" data-lesson="${i}" class="${current===i?'active':''}" ${current===i?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${l.title}</span><span class="status">${complete(i)?'✓':''}</span></a>`:'').join('')}`).join('')}<div id="overall-label" class="progress-label">${count()} / 14 lessons completed</div><div class="progress-track"><span id="overall-bar" style="width:${count()/14*100}%"></span></div><p class="micro">Progress stays in this browser.</p></aside>`;}
function lesson(i){current=i;selectedAnswer=null;const l=lessons[i];$('#app').innerHTML=`<div class="layout">${sidebar()}<main id="main" class="lesson-main"><div class="breadcrumb">Learning path / Module ${l.module} / Lesson ${String(i+1).padStart(2,'0')}</div><div class="eyebrow">Module 0${l.module} · ${l.time} minute lesson</div><h1 class="lesson-title">${l.title}</h1><p class="lesson-intro">${l.intro}</p><div class="objective"><b>By the end, you can</b>${l.goal}</div><section class="concepts" aria-label="Learn the concept">${l.cards.map((c,j)=>`<article class="concept"><h3>${j+1}. ${c[0]}</h3><p>${c[1]}</p></article>`).join('')}</section><section class="lab"><div class="lab-head"><div><small>YOUR TURN</small><h3>${labTitles[l.lab]}</h3></div><span>SAFE TO EXPERIMENT</span></div><div class="lab-body" id="lab"></div></section><section class="quiz"><div class="eyebrow">Check your understanding</div><h3 style="margin-top:12px">${l.question}</h3><div class="options">${l.options.map((o,n)=>`<button class="option" aria-pressed="false" data-answer="${n}">${String.fromCharCode(65+n)}. ${o}</button>`).join('')}</div><button id="check-answer" class="primary">Check answer →</button><details><summary>Need a hint?</summary><p>${l.hint}</p></details>${statusBox('quiz-feedback','Choose an answer. Mistakes are part of learning.')}</section><p id="checkpoint-status" class="note" role="status"></p><div class="lesson-nav"><a class="text-link" href="${i?'#lesson-'+(i-1):'#home'}">← ${i?'Previous lesson':'Learning path'}</a><a class="primary" href="${i<13?'#lesson-'+(i+1):'#home'}">${i<13?'Next lesson':'Back to learning path'} →</a></div></main></div>`;labs[l.lab]();$$('[data-answer]').forEach(b=>b.onclick=()=>{selectedAnswer=+b.dataset.answer;$$('[data-answer]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});});$('#check-answer').onclick=()=>{if(selectedAnswer===null)return feedback('quiz-feedback','Select an answer first. You can use the hint if you need help.',false);const right=selectedAnswer===l.answer;feedback('quiz-feedback',right?'Correct. '+l.why:'Not quite. '+l.hint+' Try again.',right);if(right)mark('quizzes');};updateStatus();}
const labTitles={explore:'Explore the CineSuper database',architecture:'Follow a request through the layers',constraints:'Be the database rule checker',er:'Connect the movie world',eer:'Build an identity for an episode',mapping:'Put the foreign key in its home',algebra:'A relational algebra playground',sets:'Combine and compare your data',fd:'Follow the dependency arrows',normal1:'Repair the repeating group',normal2:'Split facts by their full key',normal3:'Remove the transitive dependency',bcnf:'Will the split preserve the story?',capstone:'Your CineSuper design review'};
const labs={};
labs.explore=()=>{let seen=new Set();$('#lab').innerHTML=`<p>Open all three tables. Look for an ID that connects a review to a movie, and a movie to a genre. These are small teaching samples; review data is fictional.</p><div class="chip-row">${['movies','genres','reviews'].map(t=>`<button data-table="${t}">${t}</button>`).join('')}</div><div id="sample"></div>${statusBox()}`;$$('[data-table]').forEach(b=>b.onclick=()=>{seen.add(b.dataset.table);$$('[data-table]').forEach(x=>x.classList.toggle('selected',x===b));$('#sample').innerHTML=table({movies,genres,reviews}[b.dataset.table],b.dataset.table);if(seen.size===3)labPass('lab-feedback','You explored all three tables. reviews.movie_id links to movies.id; movies.genre_id links to genres.id.');else feedback('lab-feedback',`${seen.size} of 3 tables explored. Open the other tables to follow the links.`,true);});$('[data-table]').click();};
labs.architecture=()=>{$('#lab').innerHTML=`<p>First, click each abstraction level. Then decide where a change belongs.</p><div class="flow"><button data-layer="external"><b>Movie card</b><small>External view</small></button><span class="arrow">→</span><button data-layer="logical"><b>Movie relation</b><small>Logical schema</small></button><span class="arrow">→</span><button data-layer="physical"><b>Stored pages</b><small>Physical storage</small></button></div><div id="layer-info" class="formula">Select a layer to explore it.</div><label for="level">Where does “adding an index on movies.title” belong?</label><div class="controls"><select id="level"><option value="">Choose a level</option><option>External view</option><option>Logical schema</option><option>Physical storage</option></select><button id="layer-check">Test my choice</button></div>${statusBox()}`;$$('[data-layer]').forEach(b=>b.onclick=()=>$('#layer-info').textContent={external:'The viewer sees title and language. Internal IDs can be hidden.',logical:'movies(id, title, release_year, language, genre_id) describes the facts and their structure.',physical:'Indexes and disk pages organise access to stored records. The same logical data can be stored differently.'}[b.dataset.layer]);$('#layer-check').onclick=()=>$('#level').value==='Physical storage'?labPass('lab-feedback','Yes. The index changes how rows are found; the logical schema and movie card can stay the same.'):feedback('lab-feedback','An index concerns storage and access. Try the lowest abstraction level.',false);};
labs.constraints=()=>{let sample=reviews.map(r=>({...r}));$('#lab').innerHTML=`<p>Add a fictional review. Try a duplicate review ID, a missing movie ID, or a rating of 6. Then insert a valid review to complete this activity.</p>${table(movies,'Referenced movies',['id','title'])}<form id="review-form"><div class="controls"><label>Review ID<input id="rid" type="number" value="4" required step="1"></label><label>Movie ID<input id="mid" type="number" value="1" required step="1"></label><label>Rating (1–5)<input id="rating" type="number" value="6" required step="1"></label><button type="submit">Try insert →</button><button type="button" id="reset-reviews">Reset table</button></div></form><div id="review-table">${table(sample,'reviews (practice copy)')}</div>${statusBox()}`;$('#review-form').onsubmit=e=>{e.preventDefault();const id=+$('#rid').value,mid=+$('#mid').value,rating=+$('#rating').value;if(!Number.isSafeInteger(id)||id<1)return feedback('lab-feedback','Use a positive integer review ID in this practice activity.',false);if(sample.some(r=>r.id===id))return feedback('lab-feedback','Primary-key violation: that review ID already exists. Every review needs a unique ID.',false);if(!movies.some(m=>m.id===mid))return feedback('lab-feedback','Foreign-key violation: movie_id must refer to an existing movies.id.',false);if(!Number.isInteger(rating)||rating<1||rating>5)return feedback('lab-feedback','CHECK violation: rating must be an integer from 1 to 5.',false);sample.push({id,movie_id:mid,reviewer_name:'You',rating});$('#review-table').innerHTML=table(sample,'reviews (practice copy)');$('#rid').value=id+1;labPass('lab-feedback','Accepted. The primary key is new, the movie exists, and the rating is valid. In the real assignment, review IDs are generated automatically.');};$('#reset-reviews').onclick=()=>{sample=reviews.map(r=>({...r}));$('#review-table').innerHTML=table(sample,'reviews (practice copy)');feedback('lab-feedback','Practice rows reset. Try another constraint.',true);};};
labs.er=()=>{$('#lab').innerHTML=`<p>Choose the maximum cardinality for each link. Read the optionality below the diagram.</p><div class="flow"><div class="diagram-card"><b>GENRE</b><code>id · name</code></div><span class="arrow">→</span><div class="diagram-card"><b>MOVIE</b><code>id · title · genre_id</code></div><span class="arrow">→</span><div class="diagram-card"><b>REVIEW</b><code>id · movie_id · rating</code></div></div><div class="controls"><label>Genre → Movie<select id="g-card"><option value="">Choose…</option>${opts(['One-to-one','One-to-many','Many-to-many'])}</select></label><label>Movie → Review<select id="r-card"><option value="">Choose…</option>${opts(['One-to-one','One-to-many','Many-to-many'])}</select></label><button id="er-check">Check connections</button></div><p class="note">A genre has 0..N movies; a movie has 0..1 genre. A movie has 0..N reviews; a review has exactly 1 movie.</p>${statusBox()}`;$('#er-check').onclick=()=>$('#g-card').value==='One-to-many'&&$('#r-card').value==='One-to-many'?labPass('lab-feedback','Both are one-to-many. The many-side tables hold the foreign keys. A movie is allowed to have no reviews and no genre.'):feedback('lab-feedback','One genre can categorise several movies. One movie can receive several reviews. Check both links.',false);};
labs.eer=()=>{$('#lab').innerHTML=`<p>Practice extension: episode numbers restart within each series. Choose the smallest set of attributes that identifies every episode by rule.</p>${table([{series_id:101,episode_no:1,title:'The opening'},{series_id:101,episode_no:2,title:'The clue'},{series_id:202,episode_no:1,title:'The arrival'}],'CineSuper episode extension')}<div class="check-row">${['series_id','episode_no','title'].map(c=>`<label><input type="checkbox" value="${c}" class="key-part">${c}</label>`).join('')}</div><button id="episode-check">Test this key</button>${statusBox()}`;$('#episode-check').onclick=()=>{const v=$$('.key-part:checked').map(x=>x.value);v.length===2&&v.includes('series_id')&&v.includes('episode_no')?labPass('lab-feedback','Correct: (series_id, episode_no). The owner key plus the partial key identifies the weak entity. Titles are not guaranteed unique.'):feedback('lab-feedback','Use the series identity and the episode number together. Title is not a guaranteed identifier; adding it would not be minimal.',false);};};
labs.mapping=()=>{$('#lab').innerHTML=`<p>Map the two one-to-many relationships from the original assignment. Choose a home for each foreign key.</p><div class="controls"><label>genres.id is referenced by<select id="genre-home"><option value="">Choose a column</option>${opts(['movies.genre_id','genres.movie_id','reviews.genre_id'])}</select></label><label>movies.id is referenced by<select id="movie-home"><option value="">Choose a column</option>${opts(['movies.review_id','genres.movie_id','reviews.movie_id'])}</select></label><button id="map-check">Build schema →</button></div><div id="mapped"></div>${statusBox()}`;$('#map-check').onclick=()=>{if($('#genre-home').value==='movies.genre_id'&&$('#movie-home').value==='reviews.movie_id'){$('#mapped').innerHTML='<div class="formula">genres(id PK, name UNIQUE NOT NULL)<br>movies(id PK, title, …, genre_id FK NULLABLE)<br>reviews(id PK, movie_id FK NOT NULL, rating, …)</div>';labPass('lab-feedback','Mapped. Put each foreign key on the many side. A bridge table is unnecessary for these two one-to-many relationships.');}else feedback('lab-feedback','The foreign key belongs on the many side: a movie records its genre; a review records its movie.',false);};};
labs.algebra=()=>{$('#lab').innerHTML=`<p>Choose rows, then columns. Mission: display only the distinct languages in the whole sample. No typing or SQL needed.</p>${table(movies,'Input: movies')}<div class="controls"><label>Selection σ · keep rows<select id="filter-language">${opts(['All languages','Malayalam','Tamil','English'])}</select></label><label>Projection π · keep columns<select id="project">${opts(['All columns','title','language','title, language'])}</select></label><button id="run-algebra">Run operation →</button></div><div id="expression" class="formula"></div><div id="algebra-result"></div>${statusBox()}`;$('#run-algebra').onclick=()=>{const language=$('#filter-language').value,p=$('#project').value;const cols=p==='All columns'?Object.keys(movies[0]):p.split(', ');const filtered=movies.filter(m=>language==='All languages'||m.language===language);const rows=unique(filtered.map(m=>Object.fromEntries(cols.map(c=>[c,m[c]]))));$('#expression').textContent=(p==='All columns'?'':`π ${p} `)+(language==='All languages'?'(movies)':`(σ language = "${language}" (movies))`);$('#algebra-result').innerHTML=table(rows,`Result · ${rows.length} tuples`,cols);if(language==='All languages'&&p==='language')labPass('lab-feedback','Mission complete. Six movie rows become three distinct languages. Projection removes repeated tuples under set semantics.');else feedback('lab-feedback',`${rows.length} tuples returned. To complete the mission, keep all rows and project only language.`,true);};$('#run-algebra').click();};
function unique(rows){const seen=new Set();return rows.filter(r=>{const k=JSON.stringify(r);if(seen.has(k))return false;seen.add(k);return true;});}
labs.sets=()=>{let seen=new Set();$('#lab').innerHTML=`<p>A = {1, 4, 6} (featured movie IDs), B = {4, 6, 11} (saved movie IDs). Try at least three operations, including the movie–genre join.</p><div class="chip-row">${[['union','A ∪ B'],['intersection','A ∩ B'],['difference','A − B'],['product','A × B'],['join','Movies ⋈ Genres'],['division','Watched ÷ Required']].map(([v,t])=>`<button data-op="${v}">${t}</button>`).join('')}</div><div id="set-description" class="formula"></div><div id="set-result"></div>${statusBox()}`;$$('[data-op]').forEach(b=>b.onclick=()=>{const op=b.dataset.op,A=[1,4,6],B=[4,6,11];seen.add(op);$$('[data-op]').forEach(x=>x.classList.toggle('selected',x===b));let rows=[],desc='';if(op==='union'){rows=[...new Set([...A,...B])].map(movie_id=>({movie_id}));desc='Union: each movie ID found in either set, once.';}if(op==='intersection'){rows=A.filter(x=>B.includes(x)).map(movie_id=>({movie_id}));desc='Intersection: movie IDs present in both sets.';}if(op==='difference'){rows=A.filter(x=>!B.includes(x)).map(movie_id=>({movie_id}));desc='Difference: movie IDs in A but not in B. Direction matters.';}if(op==='product'){rows=A.flatMap(a=>B.map(b=>({A_movie_id:a,B_movie_id:b})));desc='Cartesian product: 3 × 3 = 9 pairs. No matching condition has been applied.';}if(op==='join'){rows=movies.flatMap(m=>genres.filter(g=>g.id===m.genre_id).map(g=>({title:m.title,genre:g.name})));desc='Theta join on movies.genre_id = genres.id. Avoid a natural join on the unrelated id columns.';}if(op==='division'){rows=[{viewer:'Anjali'}];desc='Watched = {(Anjali,1), (Anjali,6), (Ravi,1)}. Required = {1,6}. Only Anjali watched EVERY required movie.';}$('#set-description').textContent=desc;$('#set-result').innerHTML=table(rows,'Result');if(seen.size>=3&&seen.has('join'))labPass('lab-feedback','You compared at least three operations and joined movies to genres. Union-compatible sets and explicit join conditions keep the meaning clear.');else feedback('lab-feedback',`${seen.size} operations explored. Try at least three, including Movies ⋈ Genres.`,true);});};
labs.fd=()=>{$('#lab').innerHTML=`<p>Given only these rules: movie_id → title, genre_id; genre_id → genre_name. Select starting attributes and compute their closure. Mission: find the smallest key.</p><div class="check-row">${['movie_id','title','genre_id','genre_name'].map(c=>`<label><input class="closure-part" type="checkbox" value="${c}">${c}</label>`).join('')}</div><button id="closure-run">Compute closure →</button><div id="closure-result"></div>${statusBox()}`;$('#closure-run').onclick=()=>{const start=$$('.closure-part:checked').map(x=>x.value),known=new Set(start),steps=[];if(known.has('movie_id')){known.add('title');known.add('genre_id');steps.push('movie_id → add title and genre_id');}if(known.has('genre_id')){known.add('genre_name');steps.push('genre_id → add genre_name');}$('#closure-result').innerHTML=`<div class="formula">{${start.map(esc).join(', ')}}⁺ = {${[...known].map(esc).join(', ')}}<br>${steps.map(esc).join('<br>')||'No additional dependency applies.'}</div>`;if(start.length===1&&start[0]==='movie_id')labPass('lab-feedback','movie_id alone reaches every attribute: it is a candidate key under these dependencies. No proper subset can do that.');else feedback('lab-feedback',known.size===4?'This is a superkey, but contains unnecessary attributes. Try a smaller starting set.':'This set does not determine every attribute. Try starting with movie_id.',false);};};
const flatReviews=[{movie_id:1,reviewer:'Anjali',title:'Drishyam',rating:5},{movie_id:1,reviewer:'Ravi',title:'Drishyam',rating:4},{movie_id:6,reviewer:'Meera',title:'Vikram',rating:5}];
labs.normal1=()=>{$('#lab').innerHTML=`<p>A poorly designed CineSuper sheet has paired lists. Choose a repair. The pairs correspond by position.</p>${table([{movie_id:1,title:'Drishyam',reviewers:'Anjali, Ravi',ratings:'5, 4'}],'Before: repeating groups')}<div class="controls"><label>Repair strategy<select id="nf1-choice"><option value="">Choose…</option><option value="columns">Add reviewer1, reviewer2, rating1, rating2</option><option value="rows">Create one row per review</option><option value="delete">Keep only the first review</option></select></label><button id="nf1-run">Apply repair →</button></div><div id="nf1-result"></div>${statusBox()}`;$('#nf1-run').onclick=()=>{if($('#nf1-choice').value==='rows'){$('#nf1-result').innerHTML=table(flatReviews.slice(0,2),'After: 1NF teaching relation');labPass('lab-feedback','Each rating is now a single integer, and no review is lost. The repeated title remains: the next lesson repairs that dependency.');}else feedback('lab-feedback','Numbered columns repeat the group, while deleting a review loses information. Store one review in each row.',false);};};
labs.normal2=()=>{$('#lab').innerHTML=`<p>Key: (movie_id, reviewer). Assume one review per reviewer per movie. movie_id → title is a partial dependency.</p>${table(flatReviews,'ReviewSheet in 1NF')}<div class="controls"><label>Move title into…<select id="nf2-choice"><option value="">Choose…</option><option value="movie">Movie(movie_id, title)</option><option value="reviewer">Reviewer(reviewer, title)</option><option value="rating">Rating(rating, title)</option></select></label><button id="nf2-run">Decompose →</button></div><div id="nf2-result"></div>${statusBox()}`;$('#nf2-run').onclick=()=>{if($('#nf2-choice').value==='movie'){$('#nf2-result').innerHTML=`<div class="two-tables">${table(unique(flatReviews.map(r=>({movie_id:r.movie_id,title:r.title}))),'Movie')}${table(flatReviews.map(({movie_id,reviewer,rating})=>({movie_id,reviewer,rating})),'Review')}</div>`;labPass('lab-feedback','Title now depends on the whole Movie key. Review keeps the full-key fact, rating. Join the two tables on movie_id to restore the original rows.');}else feedback('lab-feedback','A title describes a movie, not a reviewer or a rating. Its determinant is movie_id.',false);};};
const movieInfo=movies.map(m=>({movie_id:m.id,title:m.title,genre_id:m.genre_id,genre_name:genres.find(g=>g.id===m.genre_id).name}));
labs.normal3=()=>{$('#lab').innerHTML=`<p>movie_id → title, genre_id and genre_id → genre_name. Choose a split, then see where the duplicated “Action” fact goes.</p>${table(movieInfo,'MovieInfo')}<div class="controls"><label>Keep genre_name with…<select id="nf3-choice"><option value="">Choose…</option><option value="title">title</option><option value="genre">genre_id in a separate Genres relation</option><option value="all">every movie row</option></select></label><button id="nf3-run">Decompose →</button></div><div id="nf3-result"></div>${statusBox()}`;$('#nf3-run').onclick=()=>{if($('#nf3-choice').value==='genre'){$('#nf3-result').innerHTML=`<div class="two-tables">${table(movieInfo.map(({movie_id,title,genre_id})=>({movie_id,title,genre_id})),'Movies')}${table(unique(movieInfo.map(({genre_id,genre_name})=>({genre_id,genre_name}))),'Genres')}</div>`;labPass('lab-feedback','Action now appears once in Genres. Both tables are in BCNF under these stated dependencies. The common genre_id determines Genres, so the split is lossless.');}else feedback('lab-feedback','genre_name describes a genre. Move it with its determinant, genre_id, rather than repeating it for every movie.',false);};};
labs.bcnf=()=>{$('#lab').innerHTML=`<p>Compare two splits of the CuratorAssignment practice relation. The stated dependencies are (movie, genre) → curator and curator → genre.</p>${table([{movie:'Drishyam',curator:'Asha',genre:'Thriller'},{movie:'Memento',curator:'Bala',genre:'Thriller'}],'Original valid relation')}<div class="controls"><label>Decomposition<select id="split"><option value="safe">(curator, genre) + (movie, curator)</option><option value="lossy">(movie, genre) + (curator, genre)</option></select></label><button id="join-back">Split & join back →</button></div><div id="split-result"></div><div class="controls"><label>The first split is…<select id="split-judgment"><option value="">Choose a conclusion</option><option value="both">Lossless and dependency preserving</option><option value="lossless">Lossless, but not dependency preserving</option><option value="bad">Lossy</option></select></label><button id="judge-split">Check conclusion</button></div>${statusBox()}`;$('#join-back').onclick=()=>{const original=[{movie:'Drishyam',curator:'Asha',genre:'Thriller'},{movie:'Memento',curator:'Bala',genre:'Thriller'}];const safe=$('#split').value==='safe';const left=unique(original.map(r=>safe?{curator:r.curator,genre:r.genre}:{movie:r.movie,genre:r.genre}));const right=unique(original.map(r=>safe?{movie:r.movie,curator:r.curator}:{curator:r.curator,genre:r.genre}));const joined=left.flatMap(a=>right.filter(b=>safe?a.curator===b.curator:a.genre===b.genre).map(b=>({...a,...b})));$('#split-result').innerHTML=`<div class="two-tables">${table(left,'First component')}${table(right,'Second component')}</div>${table(joined,`Rejoined · ${joined.length} tuples`)}<p class="note">${safe?'Exactly the original two tuples. The common curator determines one component. However, local rules alone can now allow two curators for the same (movie, genre).':'Four tuples: two are invented associations. Sharing genre does not tell us which curator worked on which movie. This split is lossy.'}</p>`;};$('#judge-split').onclick=()=>$('#split-judgment').value==='lossless'?labPass('lab-feedback','Correct. The first split is lossless and reaches BCNF, but checking (movie, genre) → curator requires looking across both tables. Lossless and dependency preserving are separate properties.'):feedback('lab-feedback','The first split reconstructs the original facts, but no single component contains movie, genre, and curator together to enforce the other rule.',false);$('#join-back').click();};
labs.capstone=()=>{$('#lab').innerHTML=`<p>Review three proposed CineSuper decisions. Choose the design that keeps the intended facts reliable.</p><div class="controls"><label>Where does genre name belong?<select id="design1"><option value="">Choose…</option><option value="bad">Repeated in every review</option><option value="good">In genres, linked from movies</option></select></label></div><div class="controls"><label>How should each review refer to its movie?<select id="design2"><option value="">Choose…</option><option value="good">Required movie_id foreign key</option><option value="bad">Only the movie title</option></select></label></div><div class="controls"><label>If you store an average rating for faster reads…<select id="design3"><option value="">Choose…</option><option value="bad">It always updates itself automatically</option><option value="good">Define refresh rules and acceptable staleness</option></select></label></div><button id="design-check" class="primary">Review my design →</button>${statusBox()}`;$('#design-check').onclick=()=>{let n=[1,2,3].filter(i=>$('#design'+i).value==='good').length;if(n===3)labPass('lab-feedback','Design approved. You separated facts by their determinants, protected the relationship, and accounted for the cost of redundant data. Finish the knowledge check to complete this lesson.');else feedback('lab-feedback',`${n}/3 decisions are sound. Keep genre facts with genres, link reviews using an ID, and plan how a stored aggregate stays current.`,false);};};
function database(){current=-1;$('#app').innerHTML=`<main id="main" class="container page-narrow"><div class="eyebrow">One world, every lesson</div><h1>Meet CineSuper.</h1><p class="lead">A movie catalogue with three connected tables. These core relationships match your existing assignment.</p><div class="objective"><b>How to read the links</b>genres.id → movies.genre_id · movies.id → reviews.movie_id<br>A movie may have no genre. Every review must have a movie.</div>${table(genres,'genres · teaching subset')}${table(movies,'movies · selected columns and rows')}${table(reviews,'reviews · fictional practice data')}<section class="resource-card"><h3>The complete assignment schema</h3><p><code>genres</code>: id (PK), name (UNIQUE, NOT NULL).</p><p><code>movies</code>: id (PK), title (NOT NULL), release_year (1900–2100), language (NOT NULL), duration_min (&gt; 0), description, poster_url, genre_id (FK, nullable), created_at.</p><p><code>reviews</code>: id (PK), movie_id (FK, NOT NULL), reviewer_name (NOT NULL), rating (NOT NULL, 1–5), comment, created_at.</p><p>Deleting a genre sets matching movies.genre_id to NULL. Deleting a movie cascades to its reviews. Optional release_year and duration_min may be NULL: their CHECK constraints do not make them required.</p><p class="micro">The lessons use a small local dataset. Activities never connect to or modify students’ Supabase databases. EER, composite-key, and curator examples are labelled teaching extensions.</p></section><a class="primary" href="#lesson-0">Start with the basics →</a></main>`;}
function glossaryPage(){current=-1;$('#app').innerHTML=`<main id="main" class="container page-narrow"><div class="eyebrow">Plain words, clear ideas</div><h1>Your DBMS glossary.</h1><p class="lead">A quick reminder when a new term appears.</p><label class="micro" for="term-search">Search a term or definition</label><br><input id="term-search" class="search" type="search" placeholder="Try “key”, “dependency”, or “join”…"><div id="term-count" class="note" role="status"></div><div id="terms" class="glossary-grid"></div></main>`;const render=()=>{const q=$('#term-search').value.toLowerCase();const entries=Object.entries(glossary).filter(([t,d])=>(t+' '+d).toLowerCase().includes(q));$('#term-count').textContent=`${entries.length} terms`;$('#terms').innerHTML=entries.length?entries.map(([t,d])=>`<article><h3>${esc(t)}</h3><p>${esc(d)}</p></article>`).join(''):'<p>No matching term. Try a shorter search.</p>';};$('#term-search').oninput=render;render();}
function guide(){current=-1;$('#app').innerHTML=`<main id="main" class="container page-narrow"><div class="eyebrow">For teachers & curious learners</div><h1>A gentle route into DBMS.</h1><p class="lead">Built for first-year students who have an assignment to build, but are still discovering the ideas behind it.</p><section class="resource-card"><h3>How to run a session</h3><ol><li>Ask students to predict an outcome before clicking. Work in pairs when possible.</li><li>Read the three short explanations, then complete the activity.</li><li>Use the knowledge check to discuss the reason, not just the correct option.</li><li>A lesson is marked complete only after its activity and knowledge check are passed. All lessons remain available, so students can revisit them freely.</li></ol><p>Suggested pacing: Module 1 across three sessions of 25–35 minutes; Module 2 across four sessions of 30–40 minutes, allowing time for discussion. These are estimates, not timers.</p></section><section class="resource-card"><h3>Aligned with your course</h3><p><b>26BCA0C07 · Database Design · Semester 1.</b> Module scope follows the supplied BCA_GenAI_TechManagement_2026_DBMS.pdf.</p><p><b>Module 1, lessons 1–6:</b> DBMS architecture, data models, keys and constraints, ER/EER, entities, attributes, relationships, and mapping to relations.</p><p><b>Module 2, lessons 7–14:</b> relational algebra, functional dependencies, 1NF, 2NF, 3NF, BCNF, lossless decomposition, dependency preservation, and denormalisation trade-offs.</p><p>The existing CineSuper assignment supplies the genres, movies, and reviews schema. More advanced examples are explicit hypothetical extensions. SQL programming, transactions, and indexing lessons for Modules 3 and 4 are outside this release.</p></section><section class="resource-card"><h3>Textbook foundation & sources</h3><p>Conceptual reference: Abraham Silberschatz, Henry F. Korth, and S. Sudarshan, <i>Database System Concepts</i>, 7th edition (2019): Chapter 1 (introduction), Chapter 2 (relations and relational algebra), Chapter 6 (ER design), and Chapter 7 (relational design).</p><p>Explanations and CineSuper activities are original teaching material, not reproduced textbook pages. Consult the textbook for fuller treatments and proofs.</p><p><a href="https://www.db-book.com/" target="_blank" rel="noopener">Official textbook website ↗</a> · <a href="https://www.db-book.com/slides-dir/index.html" target="_blank" rel="noopener">Authors’ chapter resources ↗</a> · <a href="https://sathishshah.github.io/cinesuper-guide/" target="_blank" rel="noopener">Existing CineSuper task guide ↗</a></p></section><section class="resource-card"><h3>Your learning record</h3><p>${count()} of 14 lessons complete. Progress is saved only in this browser on this device. No account, class roster, or server gradebook is connected. A downloaded record is self-reported practice evidence, not a verified assessment.</p><div class="controls"><button id="export-progress">Download my progress</button><button id="reset-progress">Reset learning progress</button></div><div id="reset-area"></div></section></main>`;$('#export-progress').onclick=()=>{const text='CineSuper DBMS Learning Lab\nSelf-reported local practice record\n\n'+lessons.map((l,i)=>`${i+1}. ${l.title}\nActivity: ${progress.labs.includes(i)?'Passed':'Not yet'} | Knowledge check: ${progress.quizzes.includes(i)?'Passed':'Not yet'}\n`).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='cinesuper-learning-progress.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#reset-progress').onclick=()=>{$('#reset-area').innerHTML='<p>This clears the 14 lesson checkpoints saved in this browser. Download your record first if you want to keep it.</p><button id="confirm-reset" class="accent">Yes, clear my progress</button> <button id="cancel-reset">Keep progress</button>';$('#cancel-reset').onclick=()=>$('#reset-area').innerHTML='';$('#confirm-reset').onclick=()=>{progress={labs:[],quizzes:[]};persist();guide();toast('Learning progress cleared. Start again whenever you like.');};};}
function route(){const hash=location.hash.slice(1)||'home';const match=hash.match(/^lesson-(\d+)$/);if(match&&+match[1]<lessons.length)lesson(+match[1]);else if(hash==='database')database();else if(hash==='glossary')glossaryPage();else if(hash==='guide')guide();else home();if(!storageOK)$('#app').insertAdjacentHTML('afterbegin','<div class="storage-warning" role="status">Browser storage is unavailable. Your progress lasts only for this open session.</div>');document.title=current>=0?`${lessons[current].title} · CineSuper`:'CineSuper — The DBMS Learning Lab';window.scrollTo(0,0);const main=$('#main');main.setAttribute('tabindex','-1');main.focus({preventScroll:true});}
window.addEventListener('hashchange',route);route();
